from __future__ import annotations
from typing import Annotated
from pydantic import BaseModel, ConfigDict, Field, RootModel


class Revenue(BaseModel):
    model_config = ConfigDict(
        populate_by_name=True,
    )
    min_usd: Annotated[
        int | None, Field(description="Lower estimate of annual revenue in US dollars.")
    ] = None
    max_usd: Annotated[
        int | None, Field(description="Upper estimate of annual revenue in US dollars.")
    ] = None


class Headquarters(BaseModel):
    model_config = ConfigDict(
        populate_by_name=True,
    )
    country_code: Annotated[
        str | None, Field(description="ISO 3166-1 alpha-2 country code.")
    ] = None
    region: Annotated[str | None, Field(description="State or region.")] = None
    city: Annotated[str | None, Field(description="City.")] = None
    street_address: Annotated[str | None, Field(description="Street address.")] = None
    postal_code: Annotated[str | None, Field(description="Postal code.")] = None


class Employees(BaseModel):
    model_config = ConfigDict(
        populate_by_name=True,
    )
    count: Annotated[int | None, Field(description="Employee count, when known.")] = (
        None
    )
    min: Annotated[
        int | None, Field(description="Lower bound of the headcount range.")
    ] = None
    max: Annotated[
        int | None,
        Field(description="Upper headcount bound; null for open-ended ranges."),
    ] = None


class LatestRound(BaseModel):
    model_config = ConfigDict(
        populate_by_name=True,
    )
    type: Annotated[
        str | None, Field(description="Round type, such as seed or series_b.")
    ] = None
    date: Annotated[
        str | None, Field(description="Announcement date (YYYY-MM-DD).")
    ] = None
    amount_usd: Annotated[
        int | None, Field(description="Round size in US dollars, when disclosed.")
    ] = None


class Round(BaseModel):
    model_config = ConfigDict(
        populate_by_name=True,
    )
    type: Annotated[
        str | None, Field(description="Round type, such as seed or series_b.")
    ] = None
    date: Annotated[
        str | None, Field(description="Announcement date (YYYY-MM-DD).")
    ] = None
    amount_usd: Annotated[
        int | None, Field(description="Round size in US dollars, when disclosed.")
    ] = None
    phase: Annotated[
        str | None, Field(description="Initial financing or an extension, when known.")
    ] = None


class Funding(BaseModel):
    model_config = ConfigDict(
        populate_by_name=True,
    )
    total_usd: Annotated[
        int | None, Field(description="Total disclosed funding in US dollars.")
    ] = None
    round_count: Annotated[
        int | float | None, Field(description="Number of known funding rounds.")
    ] = None
    latest_round: Annotated[
        LatestRound | None,
        Field(
            description="The most recent known funding round; null when none is known."
        ),
    ] = None
    stage: Annotated[
        str | None, Field(description="Current funding stage, when known.")
    ] = None
    rounds: Annotated[
        list[Round] | None,
        Field(description="Known historical rounds; unavailable amounts are null."),
    ] = None


class Result(BaseModel):
    model_config = ConfigDict(
        populate_by_name=True,
    )
    name: Annotated[str | None, Field(description="Company name.")] = None
    domain: Annotated[
        str | None, Field(description="The company's website domain.")
    ] = None
    description: Annotated[str | None, Field(description="What the company does.")] = (
        None
    )
    organization_type: Annotated[
        str | None,
        Field(description="Company type, such as public_company or privately_held."),
    ] = None
    operating_status: Annotated[
        str | None,
        Field(description="Operating status, such as active, acquired or closed."),
    ] = None
    stock_symbols: Annotated[
        list[str] | None, Field(description="Known stock listings and ticker symbols.")
    ] = None
    revenue: Annotated[
        Revenue | None, Field(description="Estimated annual revenue in US dollars.")
    ] = None
    industries: Annotated[
        list[str] | None, Field(description="Industries the company operates in.")
    ] = None
    founded_year: Annotated[
        int | None, Field(description="Year the company was founded.")
    ] = None
    headquarters: Annotated[
        Headquarters | None, Field(description="Where the company is headquartered.")
    ] = None
    employees: Annotated[
        Employees | None, Field(description="How many people the company employs.")
    ] = None
    funding: Annotated[Funding | None, Field(description="Known funding history.")] = (
        None
    )


class Country(RootModel[str]):
    root: Annotated[str, Field(pattern="^[A-Z]{2}$")]


class CompanySearchFilters(BaseModel):
    model_config = ConfigDict(
        extra="forbid",
        populate_by_name=True,
    )
    countries: Annotated[
        list[Country] | None,
        Field(
            description="Headquarters countries as two-letter codes, such as US or GB."
        ),
    ] = None
    employees_min: Annotated[
        int | None,
        Field(
            description="Minimum headcount; includes overlapping employee ranges.", ge=0
        ),
    ] = None
    employees_max: Annotated[
        int | None,
        Field(
            description="Maximum headcount; includes overlapping employee ranges.", ge=0
        ),
    ] = None


class KeyMetadata(BaseModel):
    model_config = ConfigDict(
        populate_by_name=True,
    )
    credits_consumed: Annotated[
        int | float | None, Field(description="Credits charged for this request.")
    ] = None
    credits_remaining: Annotated[
        int | float | None,
        Field(description="Credits remaining for your organization."),
    ] = None


class RequestTag(RootModel[str]):
    root: Annotated[str, Field(max_length=50, min_length=1)]


class CompanySearchRequest(BaseModel):
    model_config = ConfigDict(
        populate_by_name=True,
    )
    query: Annotated[
        str,
        Field(
            description="Describe the companies to find.",
            examples=["Solar startups in California that raised a Series B"],
            max_length=500,
            min_length=1,
        ),
    ]
    filters: CompanySearchFilters | None = None
    cursor: Annotated[
        str | None,
        Field(
            description="Use next_cursor with the same query and filters to fetch the next page.",
            max_length=64,
        ),
    ] = None
    tags: Annotated[
        list[RequestTag] | None,
        Field(
            description="Labels for filtering usage in the dashboard.",
            examples=[["production", "team-alpha"]],
            max_length=20,
        ),
    ] = None


class CompanySearchResponse(BaseModel):
    model_config = ConfigDict(
        populate_by_name=True,
    )
    results: Annotated[
        list[Result] | None,
        Field(
            description="Up to 10 matching companies, most relevant first by default.",
            max_length=10,
        ),
    ] = None
    next_cursor: Annotated[
        str | None,
        Field(
            description="Pass as cursor to fetch the next page; null when there are no more results."
        ),
    ] = None
    key_metadata: KeyMetadata | None = None
    request_id: Annotated[
        str | None,
        Field(
            description="Unique ID of this request, also in `X-Request-Id`. Include it when contacting support.",
            examples=["3f1c2a6e-8b4d-4c1e-9f0a-2d7b5e6c8a91"],
        ),
    ] = None


